import{_ as o,a0 as l,w as p,s as a,I as i,x as t,a1 as s,A as r,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse(`{"title":"10  個‘ls’命 令面試的問題（二） | LCTT x X-CMD","titleTemplate":false,"description":"10  個‘ls’命 令面試的問題（二） | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10  個‘ls’命 令面試的問題（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10  個‘ls’命 令面試的問題（二） | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150309 10 Useful 'ls' Command Interview Questions--Part 2","title":"10  個‘ls’命 令面試的問題（二）","tag":"201504","desc":""},"relativePath":"201504/20150309 10 Useful 'ls' Command Interview Questions--Part 2.md","filePath":"[post].md"}`),d={name:"201504/20150309 10 Useful 'ls' Command Interview Questions--Part 2.md"};function c(w,e,h,u,f,g){const n=l("Link");return p(),a("div",null,[e[14]||(e[14]=i("h1",{id:"_10-個-ls-命-令面試的問題-二",tabindex:"-1"},[t("10 個‘ls’命 令面試的問題（二） "),i("a",{class:"header-anchor",href:"#_10-個-ls-命-令面試的問題-二","aria-label":"Permalink to “10  個‘ls’命 令面試的問題（二）”"},"​")],-1)),e[15]||(e[15]=i("p",null,"這是關於文件列表命令的第二篇文章，繼續探討‘ls’命令的其他方面。該系列的第一篇文章受到了社區的高度關注，如果你錯過了該系列的第一部分，可以訪問以下地址：",-1)),i("ul",null,[i("li",null,[s(n,{href:"http://linux.cn/article-5349-1.html"},{default:r(()=>[...e[0]||(e[0]=[t("15 個‘ls’命令的面試問題（一）",-1)])]),_:1})])]),e[16]||(e[16]=m(`<p>這篇文章通過樣例來很好地展現‘ls’命令的深入應用，我們加倍小心地來寫這篇文章來保持其簡潔可理解性，同時又能提供最全面的服務。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/ls-Command-Interview-Questions.jpg" alt="10 Interview Questions on ls Command"></p><p><em>10 ‘ls’ 命令面試的問題</em></p><h3 id="_16-假如你想要以長列表的形式列出目錄中的內容-但是不打印文件創建者名稱以及文件所屬組。看看輸出有何不同之處。" tabindex="-1">16. 假如你想要以長列表的形式列出目錄中的內容，但是不打印文件創建者名稱以及文件所屬組。看看輸出有何不同之處。### <a class="header-anchor" href="#_16-假如你想要以長列表的形式列出目錄中的內容-但是不打印文件創建者名稱以及文件所屬組。看看輸出有何不同之處。" aria-label="Permalink to “16. 假如你想要以長列表的形式列出目錄中的內容，但是不打印文件創建者名稱以及文件所屬組。看看輸出有何不同之處。###”">​</a></h3><p>a. ls 命令在與‘-l’選項一起使用時會將文件以長列表格式輸出。</p><pre><code># ls -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-inLong-List-Format.gif" alt="List Files in- Long List Format"></p><p><em>以長格式列出文件</em></p><p>b. ls 命令在與‘-l’和‘--author’一起使用時，會將文件以長列表格式輸出並帶有文件創建者的名稱信息。</p><pre><code># ls -l --author
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-By-Author.gif" alt="List Files By Author"></p><p><em>列出文件的創建者</em></p><p>c. ls 命令在與‘-g’選項 一起將會列出文件名但是不帶屬主名稱。</p><pre><code># ls -g
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-Without-Printing-Author.gif" alt="List Files Without Printing Owner Name"></p><p><em>列出文件但不列出屬主</em></p><p>d. ls 命令在與&#39;-G&#39;和‘-l’選項一起將會使用長列表格式列出文件名稱但是不帶文件所屬組名稱。</p><pre><code># ls -Gl
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-Without-Printing-Group.gif" alt="List Files Without Printing Group"></p><p><em>列出文件但是不列出所屬組</em></p><h3 id="_17-使用易讀格式打印出當前目錄中的文件以及文件夾的大小-你會如何做" tabindex="-1">17. 使用易讀格式打印出當前目錄中的文件以及文件夾的大小，你會如何做？### <a class="header-anchor" href="#_17-使用易讀格式打印出當前目錄中的文件以及文件夾的大小-你會如何做" aria-label="Permalink to “17. 使用易讀格式打印出當前目錄中的文件以及文件夾的大小，你會如何做？###”">​</a></h3><p>這裏我們需要使用&#39;-h&#39;選項（人類可閲讀的、易讀的）同‘-l’或‘-s’選項與ls命令一起使用來得到想要的輸出。</p><pre><code># ls -hl
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Size-of-Files-with-ls.gif" alt="List Files in Human Readable Format"></p><p><em>以易讀格式的長列表列出文件</em></p><pre><code># ls -hs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-File-Sizes-in-Readable-Format.gif" alt="List File Sizes in Long List Format"></p><p><em>以易讀格式的短列表列出文件</em></p><p><strong>注意</strong>： ‘-h’選項使用1024（計算機中的標準）的冪，文件或文件夾的大小分別以K，M和G作為輸出單位。</p><h3 id="_18-既然-h-選項是使用1024的冪作為標準來輸出大小-那麼ls命令是否還支持其他的冪值呢" tabindex="-1">18. 既然‘-h’選項是使用1024的冪作為標準來輸出大小，那麼ls命令是否還支持其他的冪值呢？### <a class="header-anchor" href="#_18-既然-h-選項是使用1024的冪作為標準來輸出大小-那麼ls命令是否還支持其他的冪值呢" aria-label="Permalink to “18. 既然‘-h’選項是使用1024的冪作為標準來輸出大小，那麼ls命令是否還支持其他的冪值呢？###”">​</a></h3><p>存在一個選項 ‘--si’與選項‘-h’相似，不同之處在於前者以使用1000的冪，後者使用1024的冪。</p><pre><code># ls --si
</code></pre><p>所以&#39;--si&#39;也可以與‘-l’選項一起使用來按照1000的冪來輸出文件夾的大小，並且以長列表格式顯示。</p><pre><code># ls --si -l
</code></pre><p>（LCTT 譯註：此處原文參數有誤，附圖也不對，因此刪除之）</p><h3 id="_19-假如要你使用逗號-作為分隔符來打印一個目錄中的內容-可以嗎-對於長列表形式也可行嗎" tabindex="-1">19. 假如要你使用逗號‘,’作為分隔符來打印一個目錄中的內容，可以嗎？ 對於長列表形式也可行嗎？### <a class="header-anchor" href="#_19-假如要你使用逗號-作為分隔符來打印一個目錄中的內容-可以嗎-對於長列表形式也可行嗎" aria-label="Permalink to “19. 假如要你使用逗號‘,’作為分隔符來打印一個目錄中的內容，可以嗎？ 對於長列表形式也可行嗎？###”">​</a></h3><p>當然！linux的ls命令當與其選項‘-m’一起使用時可以在打印目錄內容時以逗號‘,’分割。由於逗號分割的內容是水平填充的，ls命令不能在垂直列出內容時使用逗號來分割內容。</p><pre><code># ls -m
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Print-Contents-of-Directory-by-Comma.gif" alt="Print Contents of Directory by Comma"></p><p><em>以逗號分隔顯示內容</em></p><p>當使用長列表格式時，‘-m’選項就沒有什麼效果了。</p><pre><code># ls -ml
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Listing-Content-Horizentally.gif" alt="Listing Content Horizontally"></p><p><em>長列表不能使用逗號分隔列表</em></p><h3 id="_20-有辦法將目錄的內容逆序打印出來嗎" tabindex="-1">20. 有辦法將目錄的內容逆序打印出來嗎？### <a class="header-anchor" href="#_20-有辦法將目錄的內容逆序打印出來嗎" aria-label="Permalink to “20. 有辦法將目錄的內容逆序打印出來嗎？###”">​</a></h3><p>可以！上面的情形可以輕鬆地通過&#39;-r&#39;選項搞定，該選項將輸出順序倒置。這個選項也可以與‘-l’選項一起使用。</p><pre><code># ls -r
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Content-in-Reverse-Order.gif" alt="List Content in Reverse Order"></p><p><em>逆序列出</em></p><pre><code># ls -rl
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Long-List-Content-in-Reverse-Order.gif" alt="Long List Content in Reverse Order"></p><p><em>逆序長列表</em></p><h3 id="_21-如果你被分配一個任務-來遞歸地打印各個子目錄-你會如何應付-注意-只針對子目錄而不是文件哦。" tabindex="-1">21. 如果你被分配一個任務，來遞歸地打印各個子目錄，你會如何應付？注意，只針對子目錄而不是文件哦。### <a class="header-anchor" href="#_21-如果你被分配一個任務-來遞歸地打印各個子目錄-你會如何應付-注意-只針對子目錄而不是文件哦。" aria-label="Permalink to “21. 如果你被分配一個任務，來遞歸地打印各個子目錄，你會如何應付？注意，只針對子目錄而不是文件哦。###”">​</a></h3><p>小意思！使用“-R”選項就可以輕輕鬆鬆拿下，它也可以更進一步地與其他選項如‘-l’和‘-m’選項等組合使用。</p><pre><code># ls -R
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Print-Sub-Directories-in-Recursively.gif" alt="Print Sub Directories in Recursively"></p><p><em>遞歸列出子目錄</em></p><h3 id="_22-如何按照文件大小對其進行排序" tabindex="-1">22. 如何按照文件大小對其進行排序？### <a class="header-anchor" href="#_22-如何按照文件大小對其進行排序" aria-label="Permalink to “22. 如何按照文件大小對其進行排序？###”">​</a></h3><p>linux命令列選項&#39;-S&#39;賦予了ls命令這個超能力。按照文件大小從大到小的順序排序：</p><pre><code># ls -S
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Sort-Files-in-Linux.gif" alt="Sort Files with ls Command"><em>按文件大小排序</em></p><p>按照文件大小從小到大的順序排序。</p><pre><code># ls -Sr
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Sort-Files-in-Descending-Order.gif" alt="Sort Files in Descending Order"></p><p><em>從小到大的排序</em></p><h3 id="_23-按照一行一個文件列出目錄中的內容-並且不帶額外信息的方式" tabindex="-1">23. 按照一行一個文件列出目錄中的內容，並且不帶額外信息的方式 <a class="header-anchor" href="#_23-按照一行一個文件列出目錄中的內容-並且不帶額外信息的方式" aria-label="Permalink to “23. 按照一行一個文件列出目錄中的內容，並且不帶額外信息的方式”">​</a></h3><p>選項‘-1’在此可以解決這個問題，使用‘-1’選項來使用ls命令可以將目錄中的內容按照一行一個文件並且不帶額外信息的方式進行輸出。</p><pre><code># ls -1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Files-Without-Information.gif" alt="List Files Without Information"></p><p><em>不帶其他信息，一行一個列出文件</em></p><h3 id="_24-現在委派給你一個任務-你必須將目錄中的內容輸出到終端而且需要使用雙引號引起來-你會如何做" tabindex="-1">24. 現在委派給你一個任務，你必須將目錄中的內容輸出到終端而且需要使用雙引號引起來，你會如何做？### <a class="header-anchor" href="#_24-現在委派給你一個任務-你必須將目錄中的內容輸出到終端而且需要使用雙引號引起來-你會如何做" aria-label="Permalink to “24. 現在委派給你一個任務，你必須將目錄中的內容輸出到終端而且需要使用雙引號引起來，你會如何做？###”">​</a></h3><p>有一個選項‘-Q’會將ls命令的輸出內容用雙引號引起來。</p><pre><code># ls -Q
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Print-Files-with-Double-Quotes.gif" alt="Print Files with Double Quotes"></p><p><em>輸出的文件名用引號引起來</em></p><h3 id="_25-想像一下你正在與一個包含有很多文件和文件夾的目錄打交道-你需要使目錄名顯示在文件名之前-你如何做" tabindex="-1">25. 想像一下你正在與一個包含有很多文件和文件夾的目錄打交道，你需要使目錄名顯示在文件名之前，你如何做？### <a class="header-anchor" href="#_25-想像一下你正在與一個包含有很多文件和文件夾的目錄打交道-你需要使目錄名顯示在文件名之前-你如何做" aria-label="Permalink to “25. 想像一下你正在與一個包含有很多文件和文件夾的目錄打交道，你需要使目錄名顯示在文件名之前，你如何做？###”">​</a></h3><pre><code># ls --group-directories-first
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Print-Directories-First.gif" alt="Print Directories First"></p><p><em>目錄優先顯示</em></p><p>先點到為止，我們會馬上提供該系列文章的下一部分。別換頻道，關注我們。 另外別忘了在下面的評論中提出你們寶貴的反饋信息，喜歡就分享，幫助我們得到更好的傳播吧!</p><hr>`,81)),i("p",null,[e[2]||(e[2]=t("via: ",-1)),s(n,{href:"http://www.tecmint.com/ls-interview-questions/"},{default:r(()=>[...e[1]||(e[1]=[t("http://www.tecmint.com/ls-interview-questions/",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=t("作者：",-1)),s(n,{href:"http://www.tecmint.com/author/admin/"},{default:r(()=>[...e[3]||(e[3]=[t("Ravi Saive",-1)])]),_:1}),e[7]||(e[7]=t(" 譯者：",-1)),s(n,{href:"https://github.com/theo-l"},{default:r(()=>[...e[4]||(e[4]=[t("theo-l",-1)])]),_:1}),e[8]||(e[8]=t(" 校對：",-1)),s(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=t("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[9]||(e[9]=[t("LCTT",-1)])]),_:1}),e[12]||(e[12]=t(" 原創翻譯，",-1)),s(n,{href:"http://linux.cn/"},{default:r(()=>[...e[10]||(e[10]=[t("Linux中國",-1)])]),_:1}),e[13]||(e[13]=t(" 榮譽推出",-1))])])}const P=o(d,[["render",c]]);export{C as __pageData,P as default};
